           <label [for]="'tag-' + tag.id">
             {{ tag.name }}
           </label>
         </div>
      </div>
      <ng-template #noTags>
        <p class="no-tags-message">登録されているタグがありません。</p>
      </ng-template>
    </div>
  `,
